import Quicker from "Quicker";
import { Button, Field, Panel, Stack, TextField, useQuickerStorage } from "QuickerUi";

export default function App() {
  const input = Quicker.getInput() ?? {};
  const [name, setName] = useQuickerStorage("name", input.name ?? "");

  return (
    <main className="qk-ui-page">
      <Panel
        title={input.title ?? "React 界面"}
        footer={
          <>
            <Button onClick={() => Quicker.cancel()}>取消</Button>
            <Button
              variant="primary"
              disabled={!String(name).trim()}
              onClick={() => Quicker.close({ name: String(name).trim() })}
            >
              确定
            </Button>
          </>
        }
      >
        <Stack>
          <Field label="名称">
            <TextField value={name} wide onChange={(e) => setName(e.target.value)} />
          </Field>
        </Stack>
      </Panel>
    </main>
  );
}
